// Parse and normalize audit event
const input = $input.first().json;
const body = input.body || input;

// Validate required fields
if (!body.event && !body.action) {
  throw new Error('Missing required field: event or action');
}

// Normalize audit event structure
const auditEvent = {
  id: `audit_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  version: '1.0',

  // Event details
  event: {
    type: body.event?.type || body.action || 'unknown',
    category: body.event?.category || body.category || 'general',
    severity: body.event?.severity || body.severity || 'info',
    outcome: body.event?.outcome || body.outcome || 'success'
  },

  // Actor (who performed the action)
  actor: {
    type: body.actor?.type || 'user',
    id: body.actor?.id || body.userId || 'anonymous',
    name: body.actor?.name || body.userName || null,
    email: body.actor?.email || body.userEmail || null,
    ip: body.actor?.ip || input.headers?.['x-forwarded-for'] || input.headers?.['x-real-ip'] || null
  },

  // Resource (what was affected)
  resource: {
    type: body.resource?.type || body.resourceType || null,
    id: body.resource?.id || body.resourceId || null,
    name: body.resource?.name || body.resourceName || null
  },

  // Context
  context: {
    workflowId: $workflow.id,
    executionId: $execution.id,
    environment: process.env.NODE_ENV || 'development',
    service: body.context?.service || body.service || 'n8n',
    requestId: body.context?.requestId || input.headers?.['x-request-id'] || null
  },

  // Additional data
  data: body.data || body.details || {},

  // Metadata
  metadata: {
    source: 'audit-trail-workflow',
    createdAt: new Date().toISOString()
  }
};

return [{ json: auditEvent }];

// Mask sensitive data (PII, credentials, etc.)
const event = $input.first().json;

// Patterns for sensitive data
const sensitivePatterns = {
  email: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g,
  phone: /\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/g,
  ssn: /\b\d{3}-\d{2}-\d{4}\b/g,
  creditCard: /\b\d{4}[-\s]?\d{4}[-\s]?\d{4}[-\s]?\d{4}\b/g,
  apiKey: /\b(api[_-]?key|apikey|api[_-]?secret)[=:]?\s*['"]?([A-Za-z0-9_-]{20,})['"]?/gi,
  password: /\b(password|passwd|pwd)[=:]?\s*['"]?[^'"\s]+['"]?/gi,
  bearer: /Bearer\s+[A-Za-z0-9._-]+/gi,
  jwt: /eyJ[A-Za-z0-9_-]*\.[A-Za-z0-9_-]*\.[A-Za-z0-9_-]*/g
};

// Fields to completely redact
const redactedFields = ['password', 'secret', 'token', 'apiKey', 'privateKey', 'accessToken', 'refreshToken'];

// Mask function
function maskValue(value, pattern, replacement) {
  if (typeof value === 'string') {
    return value.replace(pattern, replacement);
  }
  return value;
}

// Redact function for entire fields
function redactObject(obj, depth = 0) {
  if (depth > 10) return obj; // Prevent infinite recursion
  if (obj === null || obj === undefined) return obj;
  if (typeof obj !== 'object') return obj;

  const result = Array.isArray(obj) ? [] : {};

  for (const [key, value] of Object.entries(obj)) {
    // Check if key should be fully redacted
    if (redactedFields.some(f => key.toLowerCase().includes(f.toLowerCase()))) {
      result[key] = '[REDACTED]';
      continue;
    }

    if (typeof value === 'object' && value !== null) {
      result[key] = redactObject(value, depth + 1);
    } else if (typeof value === 'string') {
      let masked = value;
      // Apply all masking patterns
      masked = maskValue(masked, sensitivePatterns.email, '[EMAIL_MASKED]');
      masked = maskValue(masked, sensitivePatterns.phone, '[PHONE_MASKED]');
      masked = maskValue(masked, sensitivePatterns.ssn, '[SSN_MASKED]');
      masked = maskValue(masked, sensitivePatterns.creditCard, '[CC_MASKED]');
      masked = maskValue(masked, sensitivePatterns.apiKey, '[API_KEY_MASKED]');
      masked = maskValue(masked, sensitivePatterns.password, '[PASSWORD_MASKED]');
      masked = maskValue(masked, sensitivePatterns.bearer, '[BEARER_TOKEN_MASKED]');
      masked = maskValue(masked, sensitivePatterns.jwt, '[JWT_MASKED]');
      result[key] = masked;
    } else {
      result[key] = value;
    }
  }

  return result;
}

// Mask the event data
const maskedEvent = {
  ...event,
  actor: redactObject(event.actor),
  data: redactObject(event.data),
  _piiMasked: true,
  _maskedAt: new Date().toISOString()
};

return [{ json: maskedEvent }];

// Create cryptographic signature for tamper detection
const crypto = require('crypto');
const event = $input.first().json;

// Get or initialize chain hash (in production, store in database)
const staticData = $workflow.staticData;
if (!staticData.previousHash) {
  staticData.previousHash = crypto.createHash('sha256').update('genesis').digest('hex');
}

// Create event hash
const eventString = JSON.stringify({
  id: event.id,
  timestamp: event.timestamp,
  event: event.event,
  actor: event.actor,
  resource: event.resource,
  data: event.data
});

const eventHash = crypto.createHash('sha256').update(eventString).digest('hex');

// Create chain hash (links to previous event)
const chainHash = crypto.createHash('sha256')
  .update(staticData.previousHash + eventHash)
  .digest('hex');

// Update previous hash for next event
staticData.previousHash = chainHash;
staticData.eventCount = (staticData.eventCount || 0) + 1;

const signedEvent = {
  ...event,
  integrity: {
    eventHash,
    chainHash,
    previousHash: staticData.previousHash,
    sequence: staticData.eventCount,
    algorithm: 'sha256',
    signedAt: new Date().toISOString()
  }
};

return [{ json: signedEvent }];

// Store audit log (append-only)
// In production, use a proper audit log database
const event = $input.first().json;

// Simulate append-only storage
const staticData = $workflow.staticData;
if (!staticData.auditLog) {
  staticData.auditLog = [];
}

// Append event (trim to last 1000 events for memory)
staticData.auditLog.push(event);
if (staticData.auditLog.length > 1000) {
  staticData.auditLog = staticData.auditLog.slice(-1000);
}

const stored = {
  ...event,
  storage: {
    status: 'stored',
    location: 'memory', // In production: 's3://bucket/audit-logs' or similar
    storedAt: new Date().toISOString(),
    retentionPolicy: '7years'
  }
};

return [{ json: stored }];

// Generate critical security alert
const event = $input.first().json;

const alert = {
  type: 'CRITICAL_SECURITY_ALERT',
  priority: 'P1',
  event: event,
  alertId: `alert_${Date.now()}`,
  createdAt: new Date().toISOString(),
  escalation: {
    level: 1,
    notifyChannels: ['slack', 'email', 'pagerduty'],
    requiresAck: true,
    autoEscalateAfterMinutes: 15
  },
  message: `CRITICAL: ${event.event.type} detected - Actor: ${event.actor.id}, Resource: ${event.resource?.id || 'N/A'}`
};

return [{ json: alert }];

// Analyze for security anomalies
const event = $input.first().json;
const staticData = $workflow.staticData;

// Initialize anomaly detection state
if (!staticData.securityMetrics) {
  staticData.securityMetrics = {
    failedLogins: {},
    unusualIPs: [],
    eventCounts: {}
  };
}

const metrics = staticData.securityMetrics;
const actorId = event.actor.id;
const now = Date.now();

// Check for failed login patterns
const isFailedLogin = event.event.type.includes('login') && event.event.outcome === 'failure';
if (isFailedLogin) {
  if (!metrics.failedLogins[actorId]) {
    metrics.failedLogins[actorId] = [];
  }
  metrics.failedLogins[actorId].push(now);
  // Keep only last hour
  metrics.failedLogins[actorId] = metrics.failedLogins[actorId].filter(t => now - t < 3600000);
}

// Check for anomalies
const anomalies = [];

// 5+ failed logins in an hour = brute force attempt
if (metrics.failedLogins[actorId]?.length >= 5) {
  anomalies.push({
    type: 'brute_force_attempt',
    severity: 'high',
    details: `${metrics.failedLogins[actorId].length} failed login attempts in the last hour`
  });
}

// Unusual time access (outside business hours)
const hour = new Date().getUTCHours();
if (hour < 6 || hour > 22) {
  anomalies.push({
    type: 'unusual_time_access',
    severity: 'medium',
    details: `Access at unusual hour: ${hour}:00 UTC`
  });
}

const analysis = {
  ...event,
  securityAnalysis: {
    analyzed: true,
    anomaliesDetected: anomalies.length > 0,
    anomalies,
    analyzedAt: new Date().toISOString()
  }
};

return [{ json: analysis }];

// Generate anomaly alert
const event = $input.first().json;

const alert = {
  type: 'SECURITY_ANOMALY_ALERT',
  priority: 'P2',
  event: event,
  anomalies: event.securityAnalysis.anomalies,
  alertId: `anomaly_${Date.now()}`,
  createdAt: new Date().toISOString(),
  message: `Security anomaly detected: ${event.securityAnalysis.anomalies.map(a => a.type).join(', ')}`
};

return [{ json: alert }];

// Compile final response
const inputs = $input.all();
const storedEvent = inputs.find(i => i.json.storage) || inputs[0];
const alerts = inputs.filter(i => i.json.type?.includes('ALERT'));

const response = {
  status: 'logged',
  auditId: storedEvent.json.id,
  timestamp: storedEvent.json.timestamp,
  severity: storedEvent.json.event?.severity || 'info',
  integrity: storedEvent.json.integrity,
  alerts: alerts.length > 0 ? alerts.map(a => ({
    type: a.json.type,
    priority: a.json.priority,
    alertId: a.json.alertId
  })) : [],
  storedAt: storedEvent.json.storage?.storedAt
};

return [{ json: response }];
